//! DSP defaults and DSD idle patterns (`Design.md §1.3`, `§4.3-§4.5`).
//!
//! The filters have no quality preset: every stage targets >= 140 dB image rejection (`tables.rs`,
//! `tools/design/design_halfband.py`). The modulator's input limit depends on its order and DSD rate
//! (`modulator::max_stable_input_dbfs`, generated by `tools/design/design_crfb.py`).

/// Balanced 1-bit DSD silence byte (`0x69` = `0b0110_1001`, 4 ones and 4 zeros, zero DC offset).
///
/// Per `Design.md §1.3` and `§4.5`, DSD silence is never `0x00` (which represents full-scale negative DC).
pub const DSD_IDLE_BYTE: u8 = 0x69;

/// Balanced 32-bit Native `DSD_U32_BE` silence word (`0x6969_6969`).
pub const DSD_IDLE_U32_BE: u32 = 0x6969_6969;

/// Default modulator loop order when the configuration does not choose one.
pub const DEFAULT_MODULATOR_ORDER: u8 = 5;

/// Default safety margin `M` in dB below the modulator's measured input limit `L` (`Design.md §4.4`).
///
/// The input limit itself belongs to the modulator (order and DSD rate):
/// see `modulator::max_stable_input_dbfs` and `DspConfiguration::apply_modulator_limits`.
pub const DEFAULT_SAFETY_MARGIN_DB: f64 = 0.5;

/// Image rejection every interpolation/decimation filter is designed for (`Design.md §4.2`).
pub const FILTER_REJECTION_TARGET_DB: f64 = 140.0;

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_idle_patterns_are_balanced() {
        assert_eq!(DSD_IDLE_BYTE.count_ones(), 4);
        assert_eq!(DSD_IDLE_U32_BE.count_ones(), 16);
    }
}
